CREATE DATABASE IF NOT EXISTS `audit_monitoring` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `audit_monitoring`;
CREATE TABLE `migrations` (`id` int unsigned NOT NULL AUTO_INCREMENT,`migration` varchar(255) NOT NULL,`batch` int NOT NULL,PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `users` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`name` varchar(255) NOT NULL,`email` varchar(255) NOT NULL,`password` varchar(255) NOT NULL,`role` varchar(255) NOT NULL DEFAULT 'AUDITOR',`remember_token` varchar(100) DEFAULT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`),UNIQUE KEY `users_email_unique` (`email`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `audits` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`name` varchar(255) NOT NULL,`year` smallint unsigned NOT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`),UNIQUE KEY `audits_name_year_unique` (`name`,`year`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `units` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`name` varchar(255) NOT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`),UNIQUE KEY `units_name_unique` (`name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `audit_findings` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`audit_id` bigint unsigned NOT NULL,`unit_id` bigint unsigned DEFAULT NULL,`no_lha` varchar(100) NOT NULL,`judul_temuan` varchar(255) DEFAULT NULL,`inisial` varchar(20) DEFAULT NULL,`rating` varchar(255) NOT NULL DEFAULT 'MEDIUM',`audit_plan` varchar(255) DEFAULT NULL,`temuan` longtext NOT NULL,`rekomendasi` longtext,`action_plan` longtext,`pic_name` varchar(255) DEFAULT NULL,`pic_id` bigint unsigned DEFAULT NULL,`target_date` date DEFAULT NULL,`status` enum('open','closed','overdue') NOT NULL DEFAULT 'open',`version` int unsigned NOT NULL DEFAULT 1,`closed_date` date DEFAULT NULL,`progress` tinyint unsigned NOT NULL DEFAULT '0',`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`),KEY `audit_findings_target_date_status_index` (`target_date`,`status`),KEY `audit_findings_no_lha_index` (`no_lha`),KEY `audit_findings_audit_id_foreign` (`audit_id`),KEY `audit_findings_unit_id_foreign` (`unit_id`),KEY `audit_findings_pic_id_foreign` (`pic_id`),CONSTRAINT `audit_findings_audit_id_foreign` FOREIGN KEY (`audit_id`) REFERENCES `audits` (`id`) ON DELETE CASCADE,CONSTRAINT `audit_findings_unit_id_foreign` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`) ON DELETE SET NULL,CONSTRAINT `audit_findings_pic_id_foreign` FOREIGN KEY (`pic_id`) REFERENCES `users` (`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `audit_finding_items` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`finding_id` bigint unsigned NOT NULL,`description` text NOT NULL,`sort_order` int unsigned NOT NULL DEFAULT 0,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`),KEY `audit_finding_items_finding_id_sort_order_index` (`finding_id`,`sort_order`),CONSTRAINT `audit_finding_items_finding_id_foreign` FOREIGN KEY (`finding_id`) REFERENCES `audit_findings` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `finding_updates` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`finding_id` bigint unsigned NOT NULL,`user_id` bigint unsigned DEFAULT NULL,`status` varchar(255) NOT NULL,`progress` tinyint unsigned NOT NULL DEFAULT '0',`notes` text,`old_target_date` date DEFAULT NULL,`new_target_date` date DEFAULT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`),KEY `finding_updates_finding_id_foreign` (`finding_id`),KEY `finding_updates_user_id_foreign` (`user_id`),CONSTRAINT `finding_updates_finding_id_foreign` FOREIGN KEY (`finding_id`) REFERENCES `audit_findings` (`id`) ON DELETE CASCADE,CONSTRAINT `finding_updates_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `finding_evidences` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`finding_id` bigint unsigned NOT NULL,`file_name` varchar(255) NOT NULL,`file_path` varchar(255) NOT NULL,`uploaded_by` bigint unsigned DEFAULT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`),KEY `finding_evidences_finding_id_foreign` (`finding_id`),KEY `finding_evidences_uploaded_by_foreign` (`uploaded_by`),CONSTRAINT `finding_evidences_finding_id_foreign` FOREIGN KEY (`finding_id`) REFERENCES `audit_findings` (`id`) ON DELETE CASCADE,CONSTRAINT `finding_evidences_uploaded_by_foreign` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `notifications` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`user_id` bigint unsigned NOT NULL,`finding_id` bigint unsigned DEFAULT NULL,`type` varchar(255) NOT NULL,`message` text NOT NULL,`is_read` tinyint(1) NOT NULL DEFAULT '0',`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`),KEY `notifications_user_id_is_read_index` (`user_id`,`is_read`),KEY `notifications_finding_id_foreign` (`finding_id`),CONSTRAINT `notifications_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,CONSTRAINT `notifications_finding_id_foreign` FOREIGN KEY (`finding_id`) REFERENCES `audit_findings` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
